---@class TrailRewardsDialog
---@field StateDownRankNode                UnityEngine.RectTransform
---@field StateStayRankNode                UnityEngine.RectTransform
---@field StateUpRankNode                UnityEngine.RectTransform
---@field TopNode                        UnityEngine.RectTransform
---@field PromoteTipNode                    UnityEngine.RectTransform
---@field DescriptionText                UnityEngine.RectTransform
---@field RankInPrefabTab                UnityEngine.RectTransform
---@field RankText                        UnityEngine.UI.Text
---@field RankIcon                        UnityEngine.RectTransform
---@field RightPanel                        UnityEngine.RectTransform
---@field LeftPanel                        UnityEngine.RectTransform
local TrailRewardsDialog = Class("TrailRewardsDialog")

function TrailRewardsDialog:__init()
    self.selectedSegment = 1
    self.__toggleAction = nil
    self.maxSegmentId = 0
    self.tabGroup = nil
end

function TrailRewardsDialog:__delete()
    self.selectedSegment = 1
    self.maxSegmentId = 0
    self.__toggleAction = nil
    self.tabGroup = nil
    self.controller = nil
end

function TrailRewardsDialog:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    ---@type Engine.UI.TabGroup
    local tabGroup = KTool.GetComponent(self.LeftPanel.gameObject, typeof(TabGroup))
    self.tabGroup = tabGroup
    self.__toggleAction = function(id, isOn)
        if self.selectedSegment == id then
            return
        end
        self.selectedSegment = id
        self:ResetFilterIconState()
        ---更新右侧ui
        self:FreshRewardUI(self.selectedSegment)
    end
    tabGroup.OnTabChangeEvent:AddListener(self.__toggleAction)
end

---ResetFilterIconState
function TrailRewardsDialog:ResetFilterIconState()
    local segment = trailBattleMgr:GetMySegment()
    local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
    if checkInt(segmentVo.id) == checkInt(segment) then
        ---选中当前
        ---@type UnityEngine.Transform
        local transform = self.LeftPanel.transform
        local length = transform.childCount
        for i = 1, length do
            ---@type UnityEngine.Transform
            local childTran = transform:GetChild(i - 1)
            ---@type Engine.UI.TabButton
            local tabButton = KTool.GetComponent(childTran.gameObject, typeof(TabButton))
            --local textTrans = childTran:Find('Text')
            local iconTran = childTran:Find('Icon')
            local buttonTran = childTran:Find('StateButton')
            if iconTran then
                local image = KTool.GetComponent(iconTran.gameObject, typeof(Image))
                if tabButton.id == segment then
                    KTool.SetActive(buttonTran.gameObject, true)
                else
                    KTool.SetActive(buttonTran.gameObject, false)
                end
                if self.selectedSegment == tabButton.id then
                    image.color = XLuaUtils.HexToColor('333333')
                    childTran.transform:GetComponent(typeof(Image)).enabled = false
                else
                    image.color = XLuaUtils.HexToColor('9f9f9f')
                    childTran.transform:GetComponent(typeof(Image)).enabled = true
                end
            end
        end
    end
end

---FreshTabGroup
function TrailRewardsDialog:FreshTabGroup(segment)
    local segmentVos = trailBattleMgr:GetSegments()
    KTool.DestroyGameObjectChildren(self.LeftPanel.gameObject, true)
    if isTable(segmentVos) then
        self.maxSegmentId = checkInt(table.takeLast(segmentVos).id)
        for i, vo in pairs(segmentVos) do
            ---@type UnityEngine.GameObject
            local go = KTool.Instantiate(self.LeftPanel.gameObject, self.RankInPrefabTab.gameObject, false)
            KTool.SetActive(go, true)
            ---@type Engine.UI.TabButton
            local tabButton = KTool.GetComponent(go, typeof(TabButton))
            tabButton.group = self.tabGroup
            tabButton.id = checkInt(vo.id)
            self.tabGroup:AddTabButton(tabButton)
            if segment == checkInt(vo.id) then
                self.selectedSegment = segment
            end
            local textTrans = go.transform:Find('Text')
            local iconTran = go.transform:Find('Icon')
            if textTrans and iconTran then
                KTool.GetComponent(textTrans.gameObject, typeof(Text)).text = tostring(vo.name)
                KTool.GetOrAddComponent(iconTran.gameObject, typeof(ImageAlterable)):LoadSprite(trailBattleMgr:GetSegmentIconPath(vo.id, true))
            end
        end
        self.tabGroup.TabIndex = segment
        self:ResetFilterIconState()
    end
end

---FreshRewardUI
---刷新奖励页面相关的数据
---@param segment number
function TrailRewardsDialog:FreshRewardUI(segment)
    local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment)
    self.RankText.text = tostring(segmentVo.name)
    KTool.GetOrAddComponent(self.RankIcon.gameObject, typeof(ImageAlterable)):LoadSprite(trailBattleMgr:GetSegmentIconPath(segment, true))
    local rankUp, rankStay, rankDown = 0,0,0
    if segmentVo.upGrade ~= 0 then
        rankUp = checkInt(segmentVo.upGrade[2]) - checkInt(segmentVo.upGrade[1]) + 1
    end
    if segmentVo.keepGrade ~= 0 then
        rankStay = checkInt(segmentVo.keepGrade[2]) - checkInt(segmentVo.keepGrade[1]) + 1
    end
    if segmentVo.downGrade ~= 0 then
        rankDown = checkInt(segmentVo.downGrade[2]) - checkInt(segmentVo.downGrade[1]) + 1
    end

    if segment == self.maxSegmentId then
        ---最大等级
        KTool.SetActive(self.TopNode.gameObject, true)
        KTool.SetActive(self.StateUpRankNode.gameObject, false)
        local luaBehaviour = GetLuaBehaviour(self.TopNode.gameObject, RewardBestNodeLuaPath)
        if luaBehaviour then
            if isNull(luaBehaviour.Env) then
                luaBehaviour:Init()
            end
            ---@type TrailRewardBestNode
            local env = luaBehaviour.Env
            ---@type TrailSegmentRewardVo
            local rewardVo = trailBattleMgr:GetSegmentRewardVoBySegment(-1)
            env:FreshUI(rewardVo)
        end
        KTool.SetActive(self.StateStayRankNode.gameObject, rankStay > 0)
        KTool.SetActive(self.StateDownRankNode.gameObject, rankDown > 0)

        if rankStay > 0 then
            ---偷懒的做法
            local luaBehaviour = GetLuaBehaviour(self.StateStayRankNode.gameObject, RewardNormalNodeLuaPath)
            if luaBehaviour then
                if isNull(luaBehaviour.Env) then
                    luaBehaviour:Init()
                end
                ---@type TrailRewardNormalNode
                local env = luaBehaviour.Env
                local rewards = trailBattleMgr:GetSegmentRewardVoBySegment(segment)
                env:FreshUI(rewards.keepRewards, rankStay,
                        localize('保级'),
                        localize('_num_名玩家将获得保级奖励并级持本段位', { _num_ = rankStay }),
                        string.format('No.<size=26>%d~%d</size>', 1, rankStay),
                        TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON
                )
            end
        end

        if rankDown > 0 then
            local nextSegmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment - 100)
            local luaBehaviour = GetLuaBehaviour(self.StateDownRankNode.gameObject, RewardNormalNodeLuaPath)
            if luaBehaviour then
                if isNull(luaBehaviour.Env) then
                    luaBehaviour:Init()
                end
                ---@type TrailRewardNormalNode
                local env = luaBehaviour.Env
                local rewards = trailBattleMgr:GetSegmentRewardVoBySegment(segment)
                env:FreshUI(rewards.downRewards, rankDown,
                        localize('降级'),
                        localize('_num_名玩家将获得降级奖励并回到<color=#ff3232>_name_</color>', { _num_ = rankDown, _name_ = tostring(nextSegmentVo.name) }),
                        string.format('No.<size=26>%d~%d</size>', rankStay + 1, rankStay + rankDown),
                        TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON
                )
            end
        end

    else
        KTool.SetActive(self.TopNode.gameObject, false)
        KTool.SetActive(self.StateUpRankNode.gameObject, true)
        KTool.SetActive(self.StateStayRankNode.gameObject, true)
        KTool.SetActive(self.StateDownRankNode.gameObject, true)
        if rankUp > 0 then
            ---偷懒的做法
            local nextSegmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(segment + 100)
            local luaBehaviour = GetLuaBehaviour(self.StateUpRankNode.gameObject, RewardNormalNodeLuaPath)
            if luaBehaviour then
                if isNull(luaBehaviour.Env) then
                    luaBehaviour:Init()
                end
                ---@type TrailRewardNormalNode
                local env = luaBehaviour.Env
                local rewards = trailBattleMgr:GetSegmentRewardVoBySegment(segment)
                env:FreshUI(rewards.upRewards, rankUp,
                        localize('晋级'),
                        localize('_num_名玩家将获得晋级奖励并进入<color=#ff3232>_name_</color>', { _num_ = rankUp, _name_ = tostring(nextSegmentVo.name) }),
                        string.format('No.<size=26>%d~%d</size>', 1, rankUp),
                        TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.UP_BUTTON
                )
            end
        end
        ---正常情况下三个都显示
        if rankStay > 0 then
            ---偷懒的做法
            local luaBehaviour = GetLuaBehaviour(self.StateStayRankNode.gameObject, RewardNormalNodeLuaPath)
            if luaBehaviour then
                if isNull(luaBehaviour.Env) then
                    luaBehaviour:Init()
                end
                ---@type TrailRewardNormalNode
                local env = luaBehaviour.Env
                local rewards = trailBattleMgr:GetSegmentRewardVoBySegment(segment)
                env:FreshUI(rewards.keepRewards, rankStay,
                        localize('保级'),
                        localize('_num_名玩家将获得保级奖励并级持本段位', { _num_ = rankStay }),
                        string.format('No.<size=26>%d~%d</size>', rankUp + 1, rankUp + rankStay),
                        TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.STAY_BUTTON
                )
            end
        end
        if rankDown >= 0 then
            local preNo = segment - 100
            local text = ''
            if preNo >= 100 then
                local nextSegmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(preNo)
                text = localize('_num_名玩家将获得降级奖励并回到<color=#ff3232>_name_</color>', { _num_ = rankDown, _name_ = tostring(nextSegmentVo.name) })
            else
                text = ''
            end

            local luaBehaviour = GetLuaBehaviour(self.StateDownRankNode.gameObject, RewardNormalNodeLuaPath)
            if luaBehaviour then
                if isNull(luaBehaviour.Env) then
                    luaBehaviour:Init()
                end
                ---@type TrailRewardNormalNode
                local env = luaBehaviour.Env
                local rewards = trailBattleMgr:GetSegmentRewardVoBySegment(segment)
                env:FreshUI(rewards.downRewards, rankDown,
                        localize('降级'),
                        text,
                        string.format('No.<size=26>%d~%d</size>', rankUp + rankStay + 1, rankUp + rankStay + rankDown),
                        TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.DOWN_BUTTON
                )
            end
        end
    end
end

function TrailRewardsDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.GetComponent(self.DescriptionText.gameObject, typeof(Text)).text = localize('未完成关卡的玩家将无法获取奖励并降级')
        local segment = trailBattleMgr:GetMySegment()
        xTry(function ()
            self:FreshTabGroup(segment)
            self:FreshRewardUI(segment)
        end)

    end))
    return coWait
end

function TrailRewardsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.__toggleAction then
            self.tabGroup.OnTabChangeEvent:RemoveListener(self.__toggleAction)
            self.__toggleAction = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailRewardsDialog